// Package cmakegen renders the CMake files cppm produces.
//
// Two categories, and the distinction is load-bearing:
//
//   - User-owned: CMakeLists.txt is written once by `cppm init` and never
//     rewritten. The user may edit it freely.
//   - cppm-owned: .cppm/generated/cppm_dependencies.cmake is regenerated on
//     every sync and carries a do-not-edit banner.
//
// The generated file's public interface is a compatibility surface cppm cannot
// migrate later, because it lives inside a file cppm does not own. It is
// deliberately four names: the include path, cppm_link_dependencies(),
// CPPM_TARGETS_<dep> and CPPM_DEPENDENCIES. Everything else is prefixed _cppm_
// to mark it private. See docs/architecture.md section 5.
package cmakegen

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"github.com/mehdi-shokohi/cppm/internal/lockfile"
	"github.com/mehdi-shokohi/cppm/internal/manifest"
)

// DoNotEditBanner heads every generated file.
const DoNotEditBanner = "# Generated by cppm. DO NOT EDIT -- your changes will be overwritten.\n# Regenerate with: cppm sync\n"

// VendorKey identifies cppm-generated CMakePresets.json via the "vendor" field,
// which the preset schema reserves for exactly this purpose. sync refuses to
// overwrite a presets file that does not carry it.
const VendorKey = "cppm.dev/v1"

// CMakeLists renders the user-owned top-level CMakeLists.txt.
func CMakeLists(m *manifest.Manifest) string {
	var b strings.Builder

	fmt.Fprintf(&b, "cmake_minimum_required(VERSION %s)\n\n", m.CMake.Minimum)
	languages := "CXX"
	if m.Toolchain.C != "" {
		// Dependencies routinely contain C sources, and declaring C here is
		// also what stops CMake warning that CMAKE_C_COMPILER went unused.
		languages = "CXX C"
	}
	fmt.Fprintf(&b, "project(%s\n    VERSION %s\n    LANGUAGES %s\n)\n\n", m.Name, m.Version, languages)

	b.WriteString("# cppm-managed settings: the C++ standard from cppm.json and the\n")
	b.WriteString("# dependencies it declares, pinned by cppm.lock.\n")
	b.WriteString("#\n")
	b.WriteString("# Edit cppm.json and run 'cppm sync' to change the standard or the\n")
	b.WriteString("# dependency list. This include must come before your targets.\n")
	fmt.Fprintf(&b, "include(\"${CMAKE_CURRENT_SOURCE_DIR}/%s\")\n\n", GeneratedRelPath)

	// Non-test targets first. A test target may link the library it tests, and
	// target_link_libraries() silently treats a name that is not yet a target
	// as a plain -l flag, which fails at link time with no mention of CMake.
	var ordered []string
	for _, name := range m.TargetNames() {
		if !m.Targets[name].Test {
			ordered = append(ordered, name)
		}
	}
	ordered = append(ordered, m.TestTargetNames()...)

	if len(ordered) > 0 {
		call := "add_executable"
		if m.Targets[ordered[0]].Kind == manifest.KindLibrary {
			call = "add_library"
		}
		writeSourcesGuide(&b, ordered[0], call, len(ordered) > 1)
	}

	for i, name := range ordered {
		t := m.Targets[name]
		switch t.Kind {
		case manifest.KindLibrary:
			fmt.Fprintf(&b, "add_library(%s\n", name)
		default:
			fmt.Fprintf(&b, "add_executable(%s\n", name)
		}
		for _, s := range t.Sources {
			fmt.Fprintf(&b, "    %s\n", s)
		}
		b.WriteString(")\n\n")

		// The headers explanation is written once, against the first target.
		// Repeating it per target is how a scaffold turns into a wall of
		// comments nobody reads, including the parts that matter.
		if i == 0 {
			b.WriteString("# Where #include \"...\" searches, and the one job cppm cannot do for you:\n")
			b.WriteString("# CMake has no separate \"add a header folder\" directive, this is it. So\n")
			b.WriteString("# headers are never listed -- only the directories holding them, here.\n")
			b.WriteString("#\n")
			b.WriteString("# 'include' means include/myproj/net/socket.hpp is reached as\n")
			b.WriteString("# #include \"myproj/net/socket.hpp\". That extra directory level is what\n")
			b.WriteString("# keeps your headers from colliding with a dependency's.\n")
			b.WriteString("#\n")
			b.WriteString("# Append a folder to put it on the path too. A common one is 'src', for\n")
			b.WriteString("# headers that sit beside their .cpp and are private to the build:\n")
			fmt.Fprintf(&b, "#     target_include_directories(%s PRIVATE include src)\n", name)
			b.WriteString("# which makes src/models/User.h reachable as #include \"models/User.h\",\n")
			b.WriteString("# instead of a relative \"../../\" chain that breaks when a file moves.\n")
			b.WriteString("#\n")
			b.WriteString("# A library whose *consumers* need the headers says PUBLIC, not PRIVATE.\n")
		}
		fmt.Fprintf(&b, "target_include_directories(%s PRIVATE include)\n\n", name)

		b.WriteString("# Links the dependencies from cppm.json. Replace this with your own\n")
		b.WriteString("# target_link_libraries() calls whenever you need finer control --\n")
		b.WriteString("# cppm never rewrites this file.\n")
		if len(t.Dependencies) > 0 {
			fmt.Fprintf(&b, "cppm_link_dependencies(%s %s)\n", name, strings.Join(t.Dependencies, " "))
		} else {
			fmt.Fprintf(&b, "cppm_link_dependencies(%s)\n", name)
		}

		if t.Test {
			if lib := soleLibrary(m); lib != "" {
				b.WriteString("\n# The library under test. cppm_link_dependencies above covers the\n")
				b.WriteString("# dependencies from cppm.json; your own targets are yours to link.\n")
				fmt.Fprintf(&b, "target_link_libraries(%s PRIVATE %s)\n", name, lib)
			} else {
				b.WriteString("\n# To test code from another target, link it here, e.g.\n")
				b.WriteString("#     target_link_libraries(" + name + " PRIVATE MyLibrary)\n")
				b.WriteString("# An executable cannot be linked, so shared code belongs in a library.\n")
			}
			b.WriteString("\n# Registers the target with CTest, which is what 'cppm test' drives.\n")
			b.WriteString("# The NAME is what 'cppm test --filter' matches against.\n")
			fmt.Fprintf(&b, "add_test(NAME %s COMMAND %s)\n", name, name)
		}
		b.WriteString("\n")
	}
	return strings.TrimRight(b.String(), "\n") + "\n"
}

// writeSourcesGuide explains, in the scaffold itself, the two ways to add
// source files to a target and which one costs what.
//
// It is written here rather than only in the docs because this is the file a
// user opens when they create their second .cpp, and the failure it prevents is
// a quiet one: a source file that is never compiled produces an undefined
// symbol at link time, which says nothing about CMake or about this list.
//
// example is the target the snippets are written against, and call its
// add_executable/add_library form, so a user can paste them without renaming
// anything.
func writeSourcesGuide(b *strings.Builder, example, call string, multiTarget bool) {
	// --target is optional only while the project has one target, and a
	// --with-tests scaffold already has two. An example that errors as typed
	// teaches the wrong thing, so the flag is rendered in when it is needed.
	tflag := ""
	if multiTarget {
		tflag = " --target " + example
	}
	commands := [][2]string{
		{"cppm sources add" + tflag + " src/net", "that folder, and below"},
		{"cppm sources add" + tflag + " \"src/**/*.cpp\"", "the whole tree"},
		{"cppm sources add" + tflag + " \"src/codec/*.cpp\"", "that folder only"},
		{"cppm sources", "what the patterns match now"},
		{"cppm sources remove" + tflag + " src/net", "stop compiling them"},
	}
	width := 0
	for _, c := range commands {
		if len(c[0]) > width {
			width = len(c[0])
		}
	}
	var examples strings.Builder
	for _, c := range commands {
		fmt.Fprintf(&examples, "#        %-*s   %s\n", width, c[0], c[1])
	}

	fmt.Fprintf(b, `# ---------------------------------------------------------------------------
# Your targets -- and how to add source files to them
#
# 1. By hand, one path per line in the %[2]s() list below.
#
#    Nothing to sync: the file is compiled the next time CMake configures, and
#    'cppm build' configures. Blank lines and '#' comments are allowed inside
#    the list, so group it the way src/ is laid out:
#
#        %[2]s(%[1]s
#            src/main.cpp
#
#            # domain
#            src/models/User.cpp
#            src/services/UserService.cpp
#
#            # http
#            src/controllers/UsersController.cpp
#        )
#
#    An explicit list keeps "what does this target compile" answerable from the
#    diff, which is why it is the default.
#
# 2. By folder or wildcard, when a tree grows faster than you want to edit:
#
%[3]s#
#    Quote any pattern containing * so the shell does not expand it first.
#    '*' and '?' match inside one path segment, '**' spans directories, and a
#    bare folder means every C++ source beneath it -- the form to prefer, since
#    a file added there later needs no new pattern.
#
#    The patterns live in cppm.json. 'cppm sync' expands them and writes the
#    matched files into .cppm/generated/cppm.cmake, which attaches them to the
#    target from there -- cppm does not edit this file, ever. The trade-off is
#    the sync: a source file created since the last one is not compiled until
#    you run 'cppm sync' ('cppm build' syncs first, so building covers it).
#
# Editing "sources" in cppm.json is NOT a third way. 'init' read that list to
# write this one; changing it afterwards does nothing. This file is the build.
# ---------------------------------------------------------------------------
`, example, call, examples.String())
}

// soleLibrary returns the project's only non-test library target, or "" when
// there is none or more than one.
//
// Deliberately not a best guess: with two libraries cppm cannot know which one
// the tests are for, and a wrongly linked scaffold is worse than a comment
// telling the user what to write.
func soleLibrary(m *manifest.Manifest) string {
	found := ""
	for _, name := range m.TargetNames() {
		t := m.Targets[name]
		if t.Test || t.Kind != manifest.KindLibrary {
			continue
		}
		if found != "" {
			return ""
		}
		found = name
	}
	return found
}

// TestMainCPP renders the first test for `cppm init --with-tests`.
//
// It uses no framework on purpose: init must work offline and before any
// dependency exists, so the scaffolded suite has to compile and run with
// nothing but the standard library. Swapping in Catch2 is a later, explicit
// step, and the file says how.
func TestMainCPP(projectName string) string {
	return fmt.Sprintf(`// Tests for %s.
//
// A deliberately tiny harness: no dependencies, so 'cppm test' works the moment
// the project is created. CTest judges a test purely by its exit status, so
// returning non-zero on failure is the whole protocol.
//
// To use a real framework instead:
//
//     cppm add github:catchorg/Catch2@v3.7.1 --dev
//
// then rewrite this file against it. A --dev dependency is linked into every
// target marked "test": true in cppm.json, so no CMakeLists.txt edit is needed.

#include <cstdio>
#include <string>

namespace {

int failures = 0;

void check(bool ok, const char* expression, const char* file, int line)
{
    if (ok) {
        return;
    }
    std::fprintf(stderr, "%%s:%%d: FAILED: %%s\n", file, line, expression);
    ++failures;
}

} // namespace

#define CHECK(expression) check((expression), #expression, __FILE__, __LINE__)

int main()
{
    CHECK(1 + 1 == 2);
    CHECK(std::string("%s").empty() == false);

    if (failures > 0) {
        std::fprintf(stderr, "%%d check(s) failed\n", failures);
        return 1;
    }
    std::printf("all checks passed\n");
    return 0;
}
`, projectName, projectName)
}

// MainCPP renders a hello-world that proves the toolchain works end to end.
func MainCPP(projectName string) string {
	return fmt.Sprintf(`#include <iostream>

int main()
{
    std::cout << "Hello from %s\n";
    return 0;
}
`, projectName)
}

// GitIgnore renders the .gitignore for a new project.
//
// cppm.json and cppm.lock are deliberately NOT ignored: the manifest is intent
// and the lock is reproducibility, so both belong in version control.
func GitIgnore() string {
	return `# cppm-owned: generated files and downloaded sources
.cppm/

# Build output
build/

# Editor and OS noise
.vscode/
.idea/
.DS_Store
compile_commands.json
`
}

// GeneratedRelPath is the project-relative path of the generated include.
//
// This path is referenced from the user's own CMakeLists.txt, which cppm never
// rewrites, so it is a compatibility surface cppm cannot migrate later.
const GeneratedRelPath = ".cppm/generated/cppm.cmake"

// Managed renders the single cppm-owned CMake include.
//
// It carries two sections, in this order because it matters: the language
// settings first, so that dependencies inherit them, then the dependencies.
// Putting the standard here rather than in CMakeLists.txt is what makes
// cppm.json authoritative -- editing the manifest and running sync takes effect,
// without cppm ever touching a user-owned file.
// GlobbedSources maps a target name to the files `cppm sync` expanded from its
// "sourceGlobs" patterns. A target with no patterns, or whose patterns matched
// nothing, must be absent rather than present and empty: the generated CMake
// fails loudly on a target it was told about but cannot find, and an empty
// entry would turn that check into a false alarm.
type GlobbedSources map[string][]string

func Managed(m *manifest.Manifest, l *lockfile.Lock, cppmVersion string, globbed GlobbedSources) string {
	var b strings.Builder

	b.WriteString(DoNotEditBanner)
	fmt.Fprintf(&b, "#\n# cppm %s\n", cppmVersion)
	fmt.Fprintf(&b, "# %d dependency(ies)\n\n", len(l.Packages))

	b.WriteString("include_guard(GLOBAL)\n")
	b.WriteString("include(FetchContent)\n\n")

	// ---- language settings, from cppm.json ----
	b.WriteString("# ---------------------------------------------------------------------------\n")
	b.WriteString("# Language settings (from cppm.json \"cxx\")\n")
	b.WriteString("#\n")
	b.WriteString("# CMAKE_CXX_EXTENSIONS is set explicitly because it defaults to ON, which\n")
	b.WriteString("# compiles your code as gnu++NN and leaves dependencies on mixed dialects --\n")
	b.WriteString("# code that builds under GCC and Clang then fails under MSVC.\n")
	b.WriteString("#\n")
	b.WriteString("# Set before the dependencies below so they inherit the same standard.\n")
	b.WriteString("# ---------------------------------------------------------------------------\n")
	fmt.Fprintf(&b, "set(CMAKE_CXX_STANDARD %d)\n", m.CXX.Standard)
	fmt.Fprintf(&b, "set(CMAKE_CXX_STANDARD_REQUIRED %s)\n", onOff(m.CXX.Required))
	fmt.Fprintf(&b, "set(CMAKE_CXX_EXTENSIONS %s)\n\n", onOff(m.CXX.Extensions))

	b.WriteString("# Keyword availability differs by CMake version, so emit only what is\n")
	b.WriteString("# supported: SYSTEM is 3.25+, EXCLUDE_FROM_ALL is 3.28+. Both keep a\n")
	b.WriteString("# dependency's warnings, install rules and spare targets out of your build.\n")
	b.WriteString("set(_cppm_fc_keywords \"\")\n")
	b.WriteString("if(CMAKE_VERSION VERSION_GREATER_EQUAL 3.25)\n")
	b.WriteString("    list(APPEND _cppm_fc_keywords SYSTEM)\n")
	b.WriteString("endif()\n")
	b.WriteString("if(CMAKE_VERSION VERSION_GREATER_EQUAL 3.28)\n")
	b.WriteString("    list(APPEND _cppm_fc_keywords EXCLUDE_FROM_ALL)\n")
	b.WriteString("endif()\n\n")

	// ---- dependency classification ----
	b.WriteString("# CPPM_DEPENDENCIES holds the dependencies that ship. It is what\n")
	b.WriteString("# cppm_link_dependencies() links when called with no dependency list.\n")
	b.WriteString("#\n")
	b.WriteString("# Dependencies marked \"dev\": true in cppm.json are deliberately absent from\n")
	b.WriteString("# it, so a test framework cannot end up in a release binary. They are\n")
	b.WriteString("# tracked separately and linked only into targets marked \"test\": true.\n")
	b.WriteString("set(CPPM_DEPENDENCIES \"\")\n")
	b.WriteString("set(_cppm_dev_dependencies \"\")\n")
	b.WriteString("set(_cppm_all_dependencies \"\")\n\n")

	if len(m.TestTargetNames()) > 0 {
		b.WriteString("# Targets declared \"test\": true in cppm.json. cppm_link_dependencies() adds\n")
		b.WriteString("# the dev dependencies to these, which is what lets 'cppm add --dev' take\n")
		b.WriteString("# effect without an edit to CMakeLists.txt -- a file cppm never rewrites.\n")
		fmt.Fprintf(&b, "set(_cppm_test_targets %s)\n\n", strings.Join(m.TestTargetNames(), " "))
	} else {
		b.WriteString("set(_cppm_test_targets \"\")\n\n")
	}

	// Dependencies gate their own test suites on BUILD_TESTING, and the
	// include(CTest) at the end of this file defaults it to ON. A plain
	// (non-cache) variable set to OFF here makes their option(BUILD_TESTING ...)
	// calls no-ops under CMP0077 and their if(BUILD_TESTING) blocks false, so
	// enabling tests for this project does not also build every dependency's.
	// Restored after MakeAvailable, because the user's own tests need it.
	if len(l.Packages) > 0 {
		b.WriteString("# See the Testing section at the end of this file for why this is here.\n")
		b.WriteString("if(DEFINED BUILD_TESTING)\n")
		b.WriteString("    set(_cppm_saved_build_testing \"${BUILD_TESTING}\")\n")
		b.WriteString("endif()\n")
		b.WriteString("set(BUILD_TESTING OFF)\n\n")
	}

	var fetchNames []string

	for _, p := range l.Packages {
		fmt.Fprintf(&b, "# ---------------------------------------------------------------------------\n")
		devMark := ""
		if p.Dev {
			devMark = "   (dev: tests only)"
		}
		if p.Requested != "" {
			fmt.Fprintf(&b, "# %s @ %s%s\n", p.Name, p.Requested, devMark)
		} else {
			fmt.Fprintf(&b, "# %s%s\n", p.Name, devMark)
		}
		fmt.Fprintf(&b, "# ---------------------------------------------------------------------------\n")

		// Cache options must be set BEFORE the dependency is made available,
		// which is the only point at which they take effect. Without them every
		// dependency builds its own tests, examples and benchmarks.
		for _, k := range sortedKeys(p.Options) {
			fmt.Fprintf(&b, "set(%s %s CACHE STRING \"\" FORCE)\n", k, cmakeQuote(p.Options[k]))
		}

		switch p.Source {
		case manifest.SourcePath:
			fmt.Fprintf(&b, "add_subdirectory(%s \"${CMAKE_BINARY_DIR}/_cppm/%s\" EXCLUDE_FROM_ALL)\n",
				cmakeQuote(p.Path), p.Name)
		default:
			fmt.Fprintf(&b, "FetchContent_Declare(%s\n", p.Name)
			fmt.Fprintf(&b, "    GIT_REPOSITORY %s\n", cmakeQuote(p.URL))
			fmt.Fprintf(&b, "    GIT_TAG        %s\n", p.Commit)
			if p.ShallowOK == nil || *p.ShallowOK {
				b.WriteString("    GIT_SHALLOW    ON\n")
			}
			b.WriteString("    GIT_PROGRESS   ON\n")
			b.WriteString("    ${_cppm_fc_keywords}\n")
			b.WriteString(")\n")
			fetchNames = append(fetchNames, p.Name)
		}

		if len(p.Targets) > 0 {
			fmt.Fprintf(&b, "set(CPPM_TARGETS_%s %s)\n", p.Name, strings.Join(p.Targets, " "))
		} else {
			fmt.Fprintf(&b, "set(CPPM_TARGETS_%s \"\")\n", p.Name)
		}
		if p.Dev {
			fmt.Fprintf(&b, "list(APPEND _cppm_dev_dependencies %s)\n", p.Name)
		} else {
			fmt.Fprintf(&b, "list(APPEND CPPM_DEPENDENCIES %s)\n", p.Name)
		}
		fmt.Fprintf(&b, "list(APPEND _cppm_all_dependencies %s)\n\n", p.Name)
	}

	if len(fetchNames) > 0 {
		b.WriteString("# A single MakeAvailable call keeps resolution order predictable.\n")
		fmt.Fprintf(&b, "FetchContent_MakeAvailable(%s)\n\n", strings.Join(fetchNames, " "))
	}

	if len(l.Packages) > 0 {
		b.WriteString("# Dependencies are configured; BUILD_TESTING is this project's own again.\n")
		b.WriteString("if(DEFINED _cppm_saved_build_testing)\n")
		b.WriteString("    set(BUILD_TESTING \"${_cppm_saved_build_testing}\")\n")
		b.WriteString("else()\n")
		b.WriteString("    unset(BUILD_TESTING)\n")
		b.WriteString("endif()\n\n")
	}

	writeGlobbedSources(&b, m, globbed)

	// Verification. Because target names are partly inferred, a clear failure
	// here is a primary user experience rather than an edge case.
	b.WriteString(`# ---------------------------------------------------------------------------
# Verify that every dependency really provides the target cppm expects.
# ---------------------------------------------------------------------------
foreach(_cppm_dep IN LISTS _cppm_all_dependencies)
    foreach(_cppm_target IN LISTS CPPM_TARGETS_${_cppm_dep})
        if(NOT TARGET ${_cppm_target})
            message(FATAL_ERROR
                "cppm: dependency '${_cppm_dep}' does not provide target '${_cppm_target}'.\n"
                "cppm could not determine the right target name. Either pin it in cppm.json:\n"
                "    \"${_cppm_dep}\": { ..., \"targets\": [\"<real::target>\"] }\n"
                "or link it yourself in CMakeLists.txt -- cppm will not overwrite your edits.\n"
                "Run 'cppm info ${_cppm_dep}' to see the candidates that were considered.")
        endif()
    endforeach()
endforeach()

# ---------------------------------------------------------------------------
# cppm_link_dependencies(<target> [<dep>...])
#
# With no dependency names, links every dependency in cppm.json. With names,
# links only those. For anything finer, use CPPM_TARGETS_<dep> directly in your
# own target_link_libraries() call.
# ---------------------------------------------------------------------------
function(cppm_link_dependencies _cppm_link_target)
    if(NOT TARGET ${_cppm_link_target})
        message(FATAL_ERROR "cppm_link_dependencies: '${_cppm_link_target}' is not a target")
    endif()

    set(_cppm_wanted ${ARGN})
    if(NOT _cppm_wanted)
        set(_cppm_wanted ${CPPM_DEPENDENCIES})
        # A target declared "test": true in cppm.json also receives the dev
        # dependencies. This is the only mechanism available: cppm does not edit
        # CMakeLists.txt after init, so adding a test framework with --dev could
        # not otherwise take effect without a hand edit there.
        if("${_cppm_link_target}" IN_LIST _cppm_test_targets)
            list(APPEND _cppm_wanted ${_cppm_dev_dependencies})
        endif()
    endif()

    foreach(_cppm_dep IN LISTS _cppm_wanted)
        if(NOT DEFINED CPPM_TARGETS_${_cppm_dep})
            message(FATAL_ERROR
                "cppm_link_dependencies: unknown dependency '${_cppm_dep}'.\n"
                "Known dependencies: ${_cppm_all_dependencies}")
        endif()
        foreach(_cppm_target IN LISTS CPPM_TARGETS_${_cppm_dep})
            target_link_libraries(${_cppm_link_target} PRIVATE ${_cppm_target})
        endforeach()
    endforeach()
endfunction()

# ---------------------------------------------------------------------------
# Testing
#
# The CTest module, rather than a bare enable_testing(): it also writes the
# DartConfiguration.tcl that 'ctest -T memcheck' reads, which is how valgrind
# gets wired in later. It defines BUILD_TESTING and defaults it to ON, so
# -DBUILD_TESTING=OFF turns the whole test tree off.
#
# This sits at the END of this file, after the dependencies, and the order is
# load-bearing: a great many libraries build their own test suites when
# BUILD_TESTING is set, so defining it before the dependencies are made
# available would add every dependency's tests to your build. The section above
# forces it OFF for exactly that reason and restores it afterwards.
#
# PROJECT_IS_TOP_LEVEL keeps a cppm project that is consumed through
# add_subdirectory from switching testing on in its parent.
# ---------------------------------------------------------------------------
if(PROJECT_IS_TOP_LEVEL)
    include(CTest)
endif()
`)
	return b.String()
}

// writeGlobbedSources emits the files expanded from "sourceGlobs" and attaches
// them to their targets.
//
// Three decisions worth recording, because none is reversible cheaply:
//
// The file list is written out, not globbed by CMake. A file(GLOB) at configure
// time makes the set of translation units depend on what is on disk at that
// moment and shows up in no diff; without CONFIGURE_DEPENDS it is not even
// re-evaluated when a file appears. The cost of expanding here is that a new
// source file needs a `cppm sync` first. See internal/sources.
//
// target_sources() is deferred rather than called directly, because this file
// is included before the user's add_executable() runs -- it has to be, since
// the dependencies and the C++ standard must be set first. cmake_language(DEFER)
// runs the call at the end of the including directory, by which time the
// targets exist. The alternative was a new public variable for CMakeLists.txt
// to reference, which cppm could never migrate later.
//
// Paths are absolute via CMAKE_CURRENT_SOURCE_DIR rather than relative. A
// relative path in target_sources() is resolved against the calling directory
// under CMP0076, and the calling directory of a deferred call is not obvious to
// anyone reading this; making it explicit removes the question.
func writeGlobbedSources(b *strings.Builder, m *manifest.Manifest, globbed GlobbedSources) {
	var targets []string
	for _, name := range m.TargetNames() {
		if len(globbed[name]) > 0 {
			targets = append(targets, name)
		}
	}
	if len(targets) == 0 {
		return
	}

	b.WriteString("# ---------------------------------------------------------------------------\n")
	b.WriteString("# Sources from the \"sourceGlobs\" patterns in cppm.json\n")
	b.WriteString("#\n")
	b.WriteString("# Expanded by 'cppm sync', not globbed by CMake, so this list is reviewable\n")
	b.WriteString("# and a build is what the repository says it is. A source file added since\n")
	b.WriteString("# the last sync is NOT here yet: run 'cppm sync' (or 'cppm build', which\n")
	b.WriteString("# syncs first) to pick it up. Run 'cppm sources' to see the patterns.\n")
	b.WriteString("#\n")
	b.WriteString("# Attached by a deferred target_sources() because this file is included\n")
	b.WriteString("# before your targets exist, and cppm does not edit CMakeLists.txt.\n")
	b.WriteString("# ---------------------------------------------------------------------------\n")
	fmt.Fprintf(b, "set(_cppm_glob_targets %s)\n", strings.Join(targets, " "))
	for _, name := range targets {
		fmt.Fprintf(b, "set(_cppm_glob_sources_%s\n", name)
		for _, f := range globbed[name] {
			fmt.Fprintf(b, "    \"${CMAKE_CURRENT_SOURCE_DIR}/%s\"\n", f)
		}
		b.WriteString(")\n")
	}
	b.WriteString(`
function(_cppm_apply_globbed_sources)
    foreach(_cppm_gt IN LISTS _cppm_glob_targets)
        if(NOT TARGET ${_cppm_gt})
            message(FATAL_ERROR
                "cppm: cppm.json gives target '${_cppm_gt}' a \"sourceGlobs\" list, but\n"
                "CMakeLists.txt defines no such target.\n"
                "Either define it, e.g.\n"
                "    add_executable(${_cppm_gt} ...)\n"
                "or run 'cppm sources remove --target ${_cppm_gt} <pattern>' to drop the patterns.")
        endif()
        target_sources(${_cppm_gt} PRIVATE ${_cppm_glob_sources_${_cppm_gt}})
    endforeach()
endfunction()

cmake_language(DEFER CALL _cppm_apply_globbed_sources)

`)
}

// preset mirrors the subset of CMakePresets.json that cppm generates.
type preset struct {
	Name           string            `json:"name"`
	DisplayName    string            `json:"displayName,omitempty"`
	Generator      string            `json:"generator,omitempty"`
	BinaryDir      string            `json:"binaryDir,omitempty"`
	CacheVariables map[string]string `json:"cacheVariables,omitempty"`
}

type buildPreset struct {
	Name            string `json:"name"`
	ConfigurePreset string `json:"configurePreset"`
	// Configuration is required by multi-config generators (Visual Studio,
	// Xcode), which ignore CMAKE_BUILD_TYPE entirely and pick the
	// configuration at build time. Single-config generators ignore it, so
	// setting it always is correct and makes Windows and macOS work.
	Configuration string `json:"configuration,omitempty"`
}

// vendorStamp marks the file as cppm-generated. CMakePresets.json reserves the
// "vendor" field for tool-specific data, so this is a supported extension point
// rather than a field CMake might reject.
type vendorStamp struct {
	Generated bool   `json:"generated"`
	Version   string `json:"version"`
	Note      string `json:"note"`
}

// testPreset is a CTest preset, which `cppm test` drives through
// `ctest --preset <name>`. Schema version 2 introduced them; cppm emits 3.
type testPreset struct {
	Name            string `json:"name"`
	ConfigurePreset string `json:"configurePreset"`
	// Configuration matters for the same reason it does on a build preset:
	// Visual Studio and Xcode ignore CMAKE_BUILD_TYPE and pick at test time.
	Configuration string      `json:"configuration,omitempty"`
	Output        *testOutput `json:"output,omitempty"`
}

// testOutput configures what CTest prints.
//
// outputOnFailure defaults to on because a failing test whose output is hidden
// tells the user nothing except that something broke.
type testOutput struct {
	OutputOnFailure bool `json:"outputOnFailure,omitempty"`
}

type presetsFile struct {
	Version              int                    `json:"version"`
	CMakeMinimumRequired map[string]int         `json:"cmakeMinimumRequired"`
	Vendor               map[string]vendorStamp `json:"vendor,omitempty"`
	ConfigurePresets     []preset               `json:"configurePresets"`
	BuildPresets         []buildPreset          `json:"buildPresets"`
	TestPresets          []testPreset           `json:"testPresets"`
}

// Presets renders CMakePresets.json.
//
// Build commands wrap these rather than reimplementing CMake invocation, which
// means VS Code CMake Tools, CLion and Visual Studio read the same configuration
// the CLI uses.
//
// The compiler lives here, not in the generated include: CMAKE_CXX_COMPILER has
// to be set before project() runs, and cache variables in a preset are applied
// before configure.
func Presets(m *manifest.Manifest) (string, error) {
	cache := map[string]string{}
	if m.Toolchain.CXX != "" {
		cache["CMAKE_CXX_COMPILER"] = m.Toolchain.CXX
	}
	if m.Toolchain.C != "" {
		cache["CMAKE_C_COMPILER"] = m.Toolchain.C
	}

	mk := func(name, display string) preset {
		cv := map[string]string{
			"CMAKE_BUILD_TYPE": m.CMake.BuildTypeFor(name),
		}
		if m.CMake.WantCompileCommands() {
			cv["CMAKE_EXPORT_COMPILE_COMMANDS"] = "ON"
		}
		for k, v := range cache {
			cv[k] = v
		}
		return preset{
			Name:           name,
			DisplayName:    display,
			Generator:      m.Toolchain.Generator,
			BinaryDir:      "${sourceDir}/build/" + name,
			CacheVariables: cv,
		}
	}
	major, minor, patch := parseVersionTriple(m.CMake.Minimum)
	pf := presetsFile{
		Version:              3,
		CMakeMinimumRequired: map[string]int{"major": major, "minor": minor, "patch": patch},
		Vendor: map[string]vendorStamp{
			VendorKey: {
				Generated: true,
				Version:   Version,
				Note:      "Generated from cppm.json by 'cppm sync'. Put your own presets in CMakePresets.json's sibling CMakeUserPresets.json, which cppm never touches.",
			},
		},
		ConfigurePresets: []preset{
			mk("debug", "Debug"),
			mk("release", "Release"),
		},
		BuildPresets: []buildPreset{
			{Name: "debug", ConfigurePreset: "debug", Configuration: m.CMake.BuildTypeFor("debug")},
			{Name: "release", ConfigurePreset: "release", Configuration: m.CMake.BuildTypeFor("release")},
		},
		TestPresets: []testPreset{
			{Name: "debug", ConfigurePreset: "debug", Configuration: m.CMake.BuildTypeFor("debug"),
				Output: &testOutput{OutputOnFailure: true}},
			{Name: "release", ConfigurePreset: "release", Configuration: m.CMake.BuildTypeFor("release"),
				Output: &testOutput{OutputOnFailure: true}},
		},
	}
	b, err := json.MarshalIndent(pf, "", "  ")
	if err != nil {
		return "", err
	}
	return string(b) + "\n", nil
}

// Version is stamped into generated files; set by the CLI at startup.
var Version = "dev"

// PresetsAreCppmGenerated reports whether an existing CMakePresets.json carries
// cppm's vendor stamp.
//
// sync regenerates presets so that a toolchain change in cppm.json takes effect,
// but it must not silently discard a file somebody wrote by hand.
func PresetsAreCppmGenerated(content []byte) bool {
	var probe struct {
		Vendor map[string]json.RawMessage `json:"vendor"`
	}
	if err := json.Unmarshal(content, &probe); err != nil {
		return false
	}
	_, ok := probe.Vendor[VendorKey]
	return ok
}

func onOff(v bool) string {
	if v {
		return "ON"
	}
	return "OFF"
}

// cmakeQuote wraps a value in double quotes, escaping what CMake treats
// specially. Values originate from a manifest, so they are never trusted to be
// free of quotes or backslashes.
func cmakeQuote(s string) string {
	r := strings.NewReplacer(`\`, `\\`, `"`, `\"`, `$`, `\$`)
	return `"` + r.Replace(s) + `"`
}

func sortedKeys(m map[string]string) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

func parseVersionTriple(s string) (int, int, int) {
	var major, minor, patch int
	n, _ := fmt.Sscanf(s, "%d.%d.%d", &major, &minor, &patch)
	if n < 2 {
		return 3, 24, 0
	}
	return major, minor, patch
}
